// Published benchmark scores for the Settings > Model index tab. Every entry
// carries the page it came from; a number with no source does not go in.
export type ModelIndexKey = "intelligence" | "coding" | "agentic" | "general" | "legal" | "cost";

export interface ModelPrice {
  /** USD per 1M tokens. */
  input: number;
  cachedInput: number;
  output: number;
}

export interface ModelIndexEntry {
  provider: string;
  /** Wink model id; Antigravity ids drop their -high/-medium/-low suffix. */
  model: string;
  label: string;
  /** "all" on `cost`: one list price covers every effort. */
  effort: string;
  index: ModelIndexKey;
  /** Blended USD per 1M tokens for `cost`, the source's own scale otherwise. */
  score: number;
  price?: ModelPrice;
  source: string;
  sourceLabel: string;
  date: string;
  /** The model's own lab published it; nobody independently ran it. */
  reported?: "lab";
}

/** 7 cache hit : 2 input : 1 output, the blend Artificial Analysis charts price with. */
const listPrice = (input: number, cachedInput: number, output: number) => ({
  score: (7 * cachedInput + 2 * input + output) / 10,
  price: { input, cachedInput, output },
});

